using System.Globalization;
using Frameflow.Core;
using Frameflow.Media;

namespace Frameflow;
internal static class MultimediaCoreTests
{
    internal static void Run(string dir,Action<bool,string> check)
    {
        void Reject(Action run,string label){bool fail=false;try{run();}catch(Exception){fail=true;}check(fail,label);}
        string unique=Guid.NewGuid().ToString("N"),silent=Path.Combine(dir,"silence-"+unique+".wav"),noise=Path.Combine(dir,"noise-"+unique+".wav"),clip=Path.Combine(dir,"clip-"+unique+".wav");
        PcmTools.Generate(silent,1,false);PcmTools.Generate(noise,1,true);var info=PcmTools.Inspect(silent);check(info.Rate==16000&&info.Channels==1&&info.Duration==1,"generated silence is one-second mono PCM WAV");check(File.ReadAllBytes(silent).Skip((int)info.Offset).All(b=>b==0),"generated silence samples are zero");check(File.ReadAllBytes(noise).Skip((int)info.Offset).Any(b=>b!=0),"generated white noise contains actual nonzero samples");Reject(()=>PcmTools.Generate(silent,1,true),"test-audio generator never overwrites an existing source");Reject(()=>PcmTools.Generate(clip,0,true),"invalid test-audio duration rejected before write");
        var bytes=File.ReadAllBytes(noise);PcmTools.Clip(noise,clip,.25,.75);var sliced=PcmTools.Inspect(clip);check(sliced.Duration==.5&&sliced.Rate==info.Rate,"PCM clip keeps exact requested sample duration and format");check(File.ReadAllBytes(clip).Skip((int)sliced.Offset).SequenceEqual(bytes.Skip((int)info.Offset+8000).Take(16000)),"PCM clip sample bytes exactly match source range");PcmTools.Clip(noise,clip,0,.25);check(Directory.GetFiles(dir,Path.GetFileName(clip)+".bak-*").Length>0,"existing audio clip output gets backup before replacement");Reject(()=>PcmTools.Clip(noise,noise,0,.5),"audio clipping refuses source overwrite");Reject(()=>PcmTools.Clip(noise,clip,-1,.5),"negative clip time rejected");Reject(()=>PcmTools.Clip(noise,clip,0,2),"clip beyond audio duration rejected");check(File.ReadAllBytes(noise).SequenceEqual(bytes),"audio source bytes unchanged after clip and failures");
        var spectrum=PcmTools.Spectrum(noise,0,1,CancellationToken.None,64);var silenceSpectrum=PcmTools.Spectrum(silent,0,1,CancellationToken.None,64);byte[] a=new byte[64*128*4],b=new byte[a.Length];spectrum.CopyPixels(a,64*4,0);silenceSpectrum.CopyPixels(b,64*4,0);check(spectrum.IsFrozen&&spectrum.PixelWidth==64&&spectrum.PixelHeight==128,"FFT produces frozen cross-thread-safe bitmap");check(!a.SequenceEqual(b),"real signal spectrum differs from silence");Reject(()=>PcmTools.Spectrum(noise,0,1,new CancellationToken(true)),"FFT computation honors cancellation");Reject(()=>PcmTools.Spectrum(noise,0,121,CancellationToken.None),"FFT view length bounded");
        string settings=Path.Combine(dir,"display-test.json");var options=new DisplayOptions(Layout:"audio",Tags:2,Volume:.4,WaveGain:2,AutosaveSeconds:45,RowHeight:32,MenuLanguage:"en");options.Save(settings);check(DisplayOptions.Load(settings)==options,"display and audio preferences persist native JSON");File.WriteAllText(settings,"broken");check(DisplayOptions.Load(settings)==new DisplayOptions(),"corrupt preferences safely fall back to defaults");Reject(()=>(options with{Volume=double.NaN}).Validate(),"nonfinite volume rejected");Reject(()=>(options with{Layout="unknown"}).Save(settings),"unknown layout cannot overwrite preferences");const string text=@"{\b1}甲{\b0}\N乙";check((string)new TagDisplayConverter(0).Convert(text,typeof(string),null!,CultureInfo.InvariantCulture)==text,"full-tag presentation preserves text");check((string)new TagDisplayConverter(1).Convert(text,typeof(string),null!,CultureInfo.InvariantCulture)==@"{…}甲{…}\N乙","simplified-tag presentation keeps text and ASS line break");check((string)new TagDisplayConverter(2).Convert(text,typeof(string),null!,CultureInfo.InvariantCulture)==@"甲\N乙","hidden-tag presentation strips only display tags");
        var doc=SubtitleDocument.New();doc.Add(.5,2,"  首句  ");doc.Add(2.5,4,"  第二句  ");doc.Rows.First().Set("MarginL","0000");string original=doc.Serialize();int rowIndex=doc.Records.FindIndex(x=>x.Row!=null)+1;var request=new AutomationRequest(AutomationEngine.Example,null,original,[rowIndex],rowIndex);
        var inspected=AutomationEngine.Execute(request);check(inspected.Macros.Length==2&&inspected.Ass==null,"Lua script inspection registers two actual macros without applying edits");var result=AutomationEngine.Execute(request with{Macro=inspected.Macros[0].Name});var changed=SubtitleDocument.Parse(result.Ass!);check(changed.Rows.First().Text=="首句"&&changed.Rows.Last().Text=="  第二句  ","Lua macro changes only selected dialogue");check(changed.Rows.First().Get("MarginL")=="0000"&&changed.Rows.First().Start==.5,"Lua text edit preserves numeric formatting and original timing");check(doc.Serialize()==original&&result.Selected.SequenceEqual(new[]{rowIndex}),"Lua input remains untouched and selected raw-record indexes retained");
        AutomationResult Run(string body,string validation="")=>AutomationEngine.Execute(request with{Source="aegisub.register_macro('test','',function(subs,selected,active) "+body+" end"+validation+")",Macro="test"});
        check(Run("local x=subs[selected[1]]; x.text='ignored'; return selected").Ass==original,"Lua reads return copies and require explicit writeback");check(Run("local x=subs[selected[1]]; subs[selected[1]]=x; return selected").Ass==original,"Lua no-op writeback is byte-identical");check(Run("assert(#subs == subs.n); assert(subs[active].class=='dialogue'); return selected").Ass==original,"Lua subtitle count and active record follow ASS-file indexing");
        check(SubtitleDocument.Parse(Run("local x=subs[active]; x.start_time=700; x.end_time=2100; x.actor='actor'; x.effect='fx'; x.layer=2; x.margin_l=20; x.comment=true; subs[active]=x; return selected").Ass!).Rows.First() is var r&&r.Start==.7&&r.End==2.1&&r.Actor=="actor"&&r.Effect=="fx"&&r.Layer=="2"&&r.Get("MarginL")=="20"&&r.Comment,"Lua timing actor effect layer margin and comment fields execute");
        foreach(var (body,label) in new[]{("subs.append({})","unsupported structure writes"),("local x=subs[active]; x.end_time=-1; subs[active]=x","invalid times"),("local x=subs[active]; x.text='a\\nb'; subs[active]=x","physical newline corruption"),("local x=subs[active]; x.actor='a,b'; subs[active]=x","invalid field separators"),("subs[1]={class='unknown'}","metadata writes"),("return {999999}","invalid returned selection"),("aegisub.dialog.display({})","unsupported Lua dialogs"),("aegisub.cancel()","script cancellation"),("while true do end","unbounded Lua loop"),("table.insert(subs, {})","table-based structure bypass")})Reject(()=>Run(body),"Lua transaction rejects "+label);
        Reject(()=>Run("return selected",", function() return false end"),"Lua validation false prevents execution");Reject(()=>Run("return selected",", function(s,sel) local x=s[sel[1]]; s[sel[1]]=x; return true end"),"Lua validation cannot mutate subtitles");check(Run("assert(io==nil and os==nil and require==nil and loadfile==nil and debug==nil and luanet==nil); return selected").Ass==original,"Lua environment omits file system process network loader debug and CLR APIs");Reject(()=>AutomationEngine.Execute(request with{Source="not valid lua ?"}),"Lua syntax errors fail without editing source document");
        var custom=SubtitleDocument.Parse("[Events]\nFormat: Start, End, Style, Name, Layer, MarginL, MarginR, MarginV, Effect, Extra, Text\nDialogue: 0:00:01.00,0:00:02.00,Default,Actor,0,0000,0,0,,opaque,  hi  \n[Custom]\nopaque: unchanged\n");int ci=custom.Records.FindIndex(x=>x.Row!=null)+1;var cr=AutomationEngine.Execute(request with{Ass=custom.Serialize(),Selected=[ci],Active=ci,Macro=inspected.Macros[0].Name});check(cr.Ass!.Contains("opaque: unchanged")&&SubtitleDocument.Parse(cr.Ass).Rows.First().Get("Extra")=="opaque","Lua edit preserves unknown columns and sections");
    }
}
